import type { BookingInput, Role } from './types.ts';

const ROLES: readonly string[] = ['STUDENT', 'LECTURER', 'ADMIN'];
const isRole = (r: unknown): r is Role => typeof r === 'string' && ROLES.includes(r);

// JSON.parse gives no guarantee at runtime, so treat its result as unknown and check every field.
export function parseBookingInput(body: string): BookingInput | null {
  const raw: unknown = JSON.parse(body);
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return null;
  const o = raw as Record<string, unknown>;
  const { lab, seats, role, start, end } = o;
  if (typeof lab !== 'string' || typeof start !== 'string' || typeof end !== 'string') return null;
  if (typeof seats !== 'number' || !Number.isInteger(seats) || seats < 1) return null;
  if (!isRole(role)) return null;
  return { lab, seats, role, start, end };
}

