import type { BookingInput, Problem } from './types.ts';

export type Rule = (input: BookingInput) => Problem | null;

// maxSeats(40) builds a rule "at most 40 seats"; maxSeats(60) is the lecture-hall version.
export function maxSeats(limit) {
  return (input) => (input.seats > limit ? { code: 'TOO_MANY_SEATS', message: 'At most ' + limit + ' seats' } : null);
}

// Runs every rule and keeps the problems.
export function validate(input, rules) {
  const problems = [];
  for (const rule of rules) {
    const problem = rule(input);
    if (problem !== null) problems.push(problem);
  }
  return problems;
}

